const expected = env.get('FACIS_DEPLOY_TOKEN');
if (!expected) {
    node.error('FACIS_DEPLOY_TOKEN env var is not set on the orce pod', msg);
    msg.statusCode = 500;
    msg.payload = { ok: false, error: 'deploy endpoint not configured' };
    return [null, msg];
}
const h = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const presented = h.startsWith('Bearer ') ? h.slice(7) : '';
if (presented !== expected) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'unauthorized' };
    return [null, msg];
}
msg.uibuildername = 'aiInsight';
return [msg, null];

let buf = null;
if (Buffer.isBuffer(msg.payload)) {
    buf = msg.payload;
} else if (msg.req && msg.req.rawBody && Buffer.isBuffer(msg.req.rawBody)) {
    buf = msg.req.rawBody;
} else if (typeof msg.payload === 'string') {
    buf = Buffer.from(msg.payload, 'binary');
    node.warn('Payload arrived as string; converted using latin1. Prefer application/zip.');
} else {
    node.error('Payload is not Buffer/String and no rawBody present', msg);
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'expected application/zip body' };
    return [null, msg];
}
if (buf.length < 4 || buf[0] !== 0x50 || buf[1] !== 0x4B) {
    node.warn('Payload does not start with PK (ZIP). Check Content-Type / middleware.');
}
msg.payload = buf;
msg.filename = '/data/uibuilder/aiInsight-bundle.zip';
return [msg, null];

const name = msg.uibuildername;
const file = `/data/uibuilder/${name}/src/index.html`;
// Defensive: rewrite bare `/assets/` to `/orce/<name>/assets/`. No-op when
// the bundle was built with `base: '/orce/aiInsight/'` (the default in
// vite.config.ts) since asset URLs already include the prefix.
msg.command =
    `sh -c '[ -f "${file}" ] || { echo "index.html not found: ${file}" >&2; exit 1; }; ` +
    `sed -E -i "s#(src|href)=\\\"/assets/#\\\\1=\\\"/orce/${name}/assets/#g" "${file}"'`;
return msg;

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: true, target: '/data/uibuilder/aiInsight/src' };
return msg;

msg.statusCode = 500;
msg.headers = { 'Content-Type': 'application/json' };
const detail = (msg.payload && msg.payload.toString) ? msg.payload.toString().slice(0, 500) : '';
msg.payload = { ok: false, error: 'asset rewrite failed', detail };
return msg;
